        s.buffer = this.sndNoise(); s.loop = true; bp.type = 'bandpass'; bp.Q.value = q;
        bp.frequency.setValueAtTime(f, t0 + t);
        if (f1) bp.frequency.exponentialRampToValueAtTime(f1, t0 + t + dur);
        g.gain.setValueAtTime(0.0001, t0 + t);
        g.gain.exponentialRampToValueAtTime(vol, t0 + t + dur * 0.35);
