      root.classList.remove('fn-no-gl'); root.classList.add('fn-topo-ok');
      cv.setAttribute('data-ok', '1');

      const S = { cv, root, gl, W: 2, H: 2, dpr: 1, raf: 0, vis: true, t: 0, last: 0, stat: reduced, dx: 0, dy: 0, tx: 0, ty: 0, hx: 0, hy: 0,
        ptr: { on: false, x: 0, y: 0, last: -99 }, pulse: 1, pp: [-999, -999], uf: null, mx: -999, my: -999, ms: 0, drip0: 1.3, dirty: true, offs: [], ready: false };
      const P = 4.4;

