        const c = T.cols;
        gl.viewport(0, 0, cv.width, cv.height);
        gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
        gl.uniform2f(U.uRes, cv.width, cv.height); gl.uniform2f(U.uD, S.dx, S.dy); gl.uniform2f(U.uHome, S.hx, S.hy);
